/* AIVIC_FUNCTION_BUNDLE_START owner=generatePainMatrixByPriority exports=generatePainMatrixByPriority */
const __aivicBundle_7_generatePainMatrixByPriority = (() => {
  function generatePainMatrixByPriority(
    reasons: WithdrawalReason[]
  ): PainMatrixResult {
    const matrixId = randomUUID();
    const generatedAt = new Date().toISOString();
  
    if (!reasons || reasons.length === 0) {
      return {
        matrix_id: matrixId,
        total_rows: 0,
        total_columns: 0,
        cells: [],
        generated_at: generatedAt,
      };
    }
  
    // Group reasons by priority_level and importance_score
    const groupedByPriority = new Map<
      string,
      WithdrawalReason[]
    >();
  
    reasons.forEach((reason) => {
      const key = `${reason.priority_level}_${reason.importance_score}`;
      if (!groupedByPriority.has(key)) {
        groupedByPriority.set(key, []);
      }
      groupedByPriority.get(key)!.push(reason);
    });
  
    // Sort each group by registration_order
    groupedByPriority.forEach((group) => {
      group.sort((a, b) => a.registration_order - b.registration_order);
    });
  
    // Build cells: each row is a priority group, each column is a reason in that group
    const cells: PainMatrixCell[] = [];
    let rowIndex = 0;
  
    // Sort priority groups for consistent row ordering
    const sortedKeys = Array.from(groupedByPriority.keys()).sort();
  
    sortedKeys.forEach((key) => {
      const group = groupedByPriority.get(key)!;
      const [priorityLevel, importanceScore] = key.split("_").map(Number);
  
      group.forEach((reason, columnIndex) => {
        const cellId = randomUUID();
        cells.push({
          cell_id: cellId,
          priority_level: priorityLevel,
          importance_score: importanceScore,
          withdrawal_reason_id: reason.withdrawal_reason_id,
          reason_text: reason.reason_text,
          row_index: rowIndex,
          column_index: columnIndex,
          sort_order: columnIndex + 1,
        });
      });
  
      rowIndex++;
    });
  
    const totalRows = groupedByPriority.size;
    const totalColumns = Math.max(
      ...Array.from(groupedByPriority.values()).map((g) => g.length)
    );
  
    return {
      matrix_id: matrixId,
      total_rows: totalRows,
      total_columns: totalColumns,
      cells,
      generated_at: generatedAt,
    };
  }
  return { generatePainMatrixByPriority };
})();
export const generatePainMatrixByPriority = __aivicBundle_7_generatePainMatrixByPriority.generatePainMatrixByPriority;
/* AIVIC_FUNCTION_BUNDLE_END owner=generatePainMatrixByPriority */

