const __aivicBundle_9_analyzeNutritionAchievementRate = (() => {
  function analyzeNutritionAchievementRate(
    input: NutritionAchievementRateInput
  ): NutritionAchievementRateResult {
    // Validate user_id
    if (!input.user_id || input.user_id.trim() === '') {
      throw new Error('ユーザーIDが指定されていません');
    }
  
    // Validate target_date
    if (!input.target_date || isNaN(input.target_date.getTime())) {
      throw new Error('日付が無効です');
    }
  
    // Validate nutrition_standards
    if (!input.nutrition_standards || input.nutrition_standards.length === 0) {
      return {
        has_nutrition_logs: input.nutrition_logs && input.nutrition_logs.length > 0,
        achievement_rates: [],
        is_dashboard_renderable: false,
        error_message: '栄養基準値が設定されていません',
      };
    }
  
    const hasLogs = input.nutrition_logs && input.nutrition_logs.length > 0;
  
    // Create a map of nutrient logs by nutrient_name for quick lookup
    const logsMap = new Map<string, number>();
    if (hasLogs) {
      for (const log of input.nutrition_logs) {
        logsMap.set(log.nutrient_name, log.intake_amount);
      }
    }
  
    // Calculate achievement rates for each standard
    const achievementRates = input.nutrition_standards.map((standard) => {
      let achievementRate = 0;
  
      if (hasLogs && logsMap.has(standard.nutrient_name)) {
        const intakeAmount = logsMap.get(standard.nutrient_name)!;
        achievementRate = Math.round(
          (intakeAmount / standard.daily_target) * 100
        );
      }
  
      return {
        nutrient_name: standard.nutrient_name,
        achievement_rate: achievementRate,
      };
    });
  
    return {
      has_nutrition_logs: hasLogs,
      achievement_rates: achievementRates,
      is_dashboard_renderable: true,
      error_message: '',
    };
  }
  return { analyzeNutritionAchievementRate };
})();
