const __aivicBundle_10_calculateNutritionAchievementByAgeGroup = (() => {
  function getAgeGroupNutritionStandard(age: number): { calories: number; protein: number } {
    if (age < 1) {
      return { calories: 1000, protein: 15 };
    } else if (age < 3) {
      return { calories: 1100, protein: 18 };
    } else if (age < 6) {
      return { calories: 1200, protein: 20 };
    } else if (age < 9) {
      return { calories: 1800, protein: 30 };
    } else if (age < 12) {
      return { calories: 2000, protein: 35 };
    } else if (age < 15) {
      return { calories: 2200, protein: 40 };
    } else if (age < 18) {
      return { calories: 2400, protein: 45 };
    } else if (age < 50) {
      return { calories: 2100, protein: 50 };
    } else if (age < 65) {
      return { calories: 2000, protein: 50 };
    } else {
      return { calories: 1850, protein: 50 };
    }
  }
  
   function calculateNutritionAchievementByAgeGroup(
    family_members: FamilyMember[],
    nutrition_intake_data: Array<{ member_id: string; date: string; calories: number; protein: number }>
  ): AgeGroupNutritionInput[] {
    const results: AgeGroupNutritionInput[] = [];
  
    for (const member of family_members) {
      if (member.age < 0) {
        throw new Error(`無効な年齢: メンバー ${member.member_id} の年齢が負数です`);
      }
  
      const intakeRecord = nutrition_intake_data.find(
        (record) => record.member_id === member.member_id
      );
  
      if (!intakeRecord) {
        throw new Error(`メンバー ${member.member_id} に対応する栄養摂取データが見つかりません`);
      }
  
      const standard = getAgeGroupNutritionStandard(member.age);
  
      const caloriesAchievementScore =
        standard.calories > 0 ? (intakeRecord.calories / standard.calories) * 100 : 0;
      const proteinAchievementScore =
        standard.protein > 0 ? (intakeRecord.protein / standard.protein) * 100 : 0;
  
      results.push({
        member_id: member.member_id,
        age: member.age,
        nutrition_standard: {
          calories: standard.calories,
          protein: standard.protein,
        },
        nutrition_actual: {
          calories: intakeRecord.calories,
          protein: intakeRecord.protein,
        },
        achievement_score: {
          calories: caloriesAchievementScore,
          protein: proteinAchievementScore,
        },
      });
    }
  
    return results;
  }
  return { calculateNutritionAchievementByAgeGroup };
})();
